const main=document.querySelector('main');
const photo=(name,alt,extra='')=>`<img src="assets/${name}.jpg" alt="${alt}" ${extra}>`;
const money=n=>`TZS ${new Intl.NumberFormat('en-TZ').format(n)}`;
const products=[{id:'masaki',name:'Masaki Modular Sofa',category:'Living Room',price:2450000,image:'hero',material:'Textured upholstery',dimensions:'240 × 95 × 78 cm',color:'Terracotta'},{id:'bahari',name:'Bahari Dining Set',category:'Dining Room',price:1850000,image:'dining',material:'Natural wood',dimensions:'180 × 90 × 75 cm',color:'Natural'},{id:'kariakoo',name:'Kariakoo Accent Seat',category:'Living Room',price:680000,image:'sofa',material:'Woven upholstery',dimensions:'120 × 70 × 76 cm',color:'Coral'}];
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let cart=read('afro-cart',{}),wishlist=read('afro-wishlist',[]);cart=Object.fromEntries(Object.entries(cart).filter(([id,q])=>products.some(p=>p.id===id)&&Number.isInteger(q)&&q>0&&q<=99));wishlist=Array.isArray(wishlist)?wishlist.filter(id=>products.some(p=>p.id===id)):[];
function save(){try{localStorage.setItem('afro-cart',JSON.stringify(cart));localStorage.setItem('afro-wishlist',JSON.stringify(wishlist))}catch{}document.querySelector('#count').textContent=Object.values(cart).reduce((a,b)=>a+b,0)}
let toastTimer;function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}
function add(id){if(!products.some(p=>p.id===id))throw Error('Unknown product');cart[id]=Math.min(99,(cart[id]||0)+1);save();toast('Added to your bag')}
function card(p){return `<article class="product"><div class="product-image"><a href="#product/${p.id}">${photo(p.image,p.name+' — illustrative stock photograph','loading="lazy"')}</a><span class="badge">DAR COLLECTION</span><button class="wish" data-wish="${p.id}" aria-label="Save ${p.name}" aria-pressed="${wishlist.includes(p.id)}">${wishlist.includes(p.id)?'♥':'♡'}</button><button class="quick" data-quick="${p.id}">Quick view ↗</button></div><div class="product-info"><div><h3><a href="#product/${p.id}">${p.name}</a></h3><p>${p.category} · Sample design</p><div class="swatches" aria-label="Illustrative colour palette"><i></i><i></i><i></i></div></div><span class="price">${money(p.price)}</span></div></article>`}
function home(){return `<section class="hero">${photo('hero','Warm orange sofa in a light-filled living room','fetchpriority="high"')}<div class="hero-copy"><p class="eyebrow">CONTEMPORARY DESIGN. AFRICAN SOUL.</p><h1>Furniture that<br>feels like <em>home.</em></h1><p>Thoughtful pieces. Natural warmth.<br>For the everyday moments that matter.</p><div class="buttons"><a class="button" href="#shop">Explore the collection <span>↗</span></a><a class="text-link" href="#custom">Design your own ↗</a></div></div><div class="hero-bottom"><span>SCROLL TO FEEL AT HOME ↓</span><a class="hero-tag" href="#collections">MEET THE DAR COLLECTION<br><strong>A little warmth. A lot of character. ↗</strong></a></div></section><div class="promise"><span>Thoughtful by design</span><span>Inspired by African living</span><span>Made to feel like you</span><span>Rooted in Dar es Salaam</span></div><section class="section"><div class="section-heading"><div><p class="eyebrow">YOUR SPACE, YOUR STORY</p><h2>Room for every<br>part of life.</h2></div><p>Slow mornings. Long conversations. A quiet corner.<br>Find the pieces that bring your space to life.</p></div><div class="categories"><a class="category" href="#shop/Living%20Room">${photo('hero','An inviting living room','loading="lazy"')}<span class="category-label">Living room <span class="circle">↗</span></span></a><a class="category" href="#shop/Dining%20Room">${photo('dining','Natural wood dining room','loading="lazy"')}<span class="category-label">Dining room <span class="circle">↗</span></span></a><a class="category" href="#custom">${photo('sofa','Coral upholstered seat','loading="lazy"')}<span class="category-label">Made for you <span class="circle">↗</span></span></a></div><div class="room-links"><a href="#shop/Bedroom">Bedroom ↗</a><a href="#shop/Office">Office ↗</a><a href="#shop/Outdoor">Outdoor ↗</a><a href="#shop">Discover all rooms ↗</a></div></section><section class="section signature" id="collection"><div class="section-heading"><div><p class="eyebrow">THE DAR COLLECTION / 01</p><h2>Everyday pieces.<br>Extraordinary feeling.</h2></div><a class="text-link" href="#shop">View the collection ↗</a></div><div class="tabs" aria-label="Collection categories"><button class="active" data-home-filter="All">All pieces</button><button data-home-filter="Living Room">Living room</button><button data-home-filter="Dining Room">Dining room</button></div><div class="products" id="home-products">${products.map(card).join('')}</div><p class="muted">Concept collection · Illustrative photography and sample prices. Availability to be confirmed.</p></section><section class="split">${photo('sofa','The details of an upholstered coral seat','loading="lazy"')}<div class="split-copy"><p class="eyebrow">A PERSONAL POINT OF VIEW</p><h2>Your idea.<br>Our next<br>beautiful piece.</h2><p>A particular corner. A favourite colour. A size that’s just right. Tell us what you have in mind and start shaping a piece around your life.</p><a class="button" href="#custom">Let’s create something ↗</a></div></section><section class="section"><div class="section-heading"><div><p class="eyebrow">THE WHOLE PICTURE</p><h2>Don’t just picture it.<br>Make room for it.</h2></div><p>A considered room is more than the sum of its parts. Explore the feeling, one piece at a time.</p></div><div class="room">${photo('hero','A complete living-room inspiration setting','loading="lazy"')}<button class="hotspot" data-quick="masaki" aria-label="Explore the Masaki sofa concept">+</button><div class="room-caption"><p class="eyebrow">SHOP THE ROOM</p><p>The art of a slower afternoon. ↗</p></div></div></section><section class="split"><div class="split-copy"><p class="eyebrow">OUR ROOTS. YOUR HOME.</p><h2>A Tanzanian heart.<br>A modern<br>point of view.</h2><p>AfroFurnitures is a furniture concept rooted in the warmth of Dar es Salaam. Natural textures, generous shapes, and a belief that the best spaces tell your story.</p><a class="text-link" href="#story">Get to know us ↗</a></div>${photo('dining','Warm wood and natural materials in a dining space','loading="lazy"')}</section><section class="section"><div class="section-heading"><div><p class="eyebrow">NOTES ON LIVING WELL</p><h2>Afro Living.</h2></div><a class="text-link" href="#inspiration">A little inspiration ↗</a></div><div class="journal"><a href="#article/warmth">${photo('hero','Terracotta upholstery and greenery','loading="lazy"')}<p class="eyebrow">COLOUR & CHARACTER · 4 MIN READ</p><h3>A warmer way to come home. ↗</h3></a><a href="#article/table">${photo('dining','A simple wooden table styled for everyday living','loading="lazy"')}<p class="eyebrow">THE EVERYDAY EDIT · 3 MIN READ</p><h3>Make space for a longer conversation. ↗</h3></a></div></section>`}
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function shop(category='All'){return `<section class="page"><p class="eyebrow">FIND YOUR EVERYDAY FAVOURITE</p><h1>The collection.</h1><p>Thoughtful shapes. Warm materials. A place in your story.</p><p class="muted">Sample catalogue · Prices, dimensions, materials and photography are illustrative, not confirmed inventory.</p><div class="filterbar"><input id="search" type="search" placeholder="Find something for your space…" aria-label="Search products"><select id="category" aria-label="Filter by room">${['All','Living Room','Dining Room','Bedroom','Office','Outdoor'].map(c=>`<option ${c===category?'selected':''}>${c}</option>`).join('')}</select><select id="sort" aria-label="Sort products"><option value="featured">Featured</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option></select><select id="material" aria-label="Filter by material"><option value="All">All materials</option><option value="wood">Wood</option><option value="upholstery">Upholstery</option></select></div><p class="muted" id="results-count" aria-live="polite"></p><div class="products" id="results"></div></section>`}
function filter(){const q=document.querySelector('#search').value.toLowerCase(),cat=document.querySelector('#category').value,material=document.querySelector('#material').value;let items=products.filter(p=>(cat==='All'||p.category===cat)&&(material==='All'||p.material.toLowerCase().includes(material))&&(p.name+' '+p.category+' '+p.color).toLowerCase().includes(q));const sort=document.querySelector('#sort').value;if(sort!=='featured')items.sort((a,b)=>sort==='low'?a.price-b.price:b.price-a.price);document.querySelector('#results-count').textContent=`${items.length} ${items.length===1?'piece':'pieces'}`;document.querySelector('#results').innerHTML=items.length?items.map(card).join(''):`<div class="empty"><h2>Room for something new.</h2><p>No matching pieces in our sample collection yet. Try another filter, or tell us about your idea.</p><a class="button" href="#custom">Design your own ↗</a></div>`}
function detail(p){return `<div class="detail">${photo(p.image,p.name+' inspiration photograph')}<div><p class="eyebrow">DAR COLLECTION · SAMPLE DESIGN</p><h1>${p.name}</h1><p>${money(p.price)} <span class="muted">· Sample price</span></p><p>A little character for your everyday. This concept brings a warm material palette and an inviting silhouette into a contemporary home.</p><p class="muted">Illustrative stock photography. Final design, specification, price and availability require confirmation.</p><label>Proposed colour<select><option>${p.color}</option></select></label><button class="button" data-add="${p.id}">Add to bag <span>+</span></button><a class="text-link" href="#custom">Make it personal ↗</a><details><summary>Materials & dimensions</summary><p>${p.material}<br>${p.dimensions}<br>Indicative specification only.</p></details><details><summary>Delivery & assembly</summary><p>Delivery area, timing and assembly requirements must be agreed before an order. No delivery charge has been calculated.</p></details><details><summary>Care for your piece</summary><p>Dust gently with a soft cloth. Blot spills promptly. Keep away from direct sunlight and confirm material-specific care before using cleaning products.</p></details></div></div>`}
function bag(){const items=products.filter(p=>cart[p.id]);return `<section class="page"><p class="eyebrow">A LITTLE CLOSER TO HOME</p><h1>Your bag.</h1>${items.length?items.map(p=>`<div class="cart-row">${photo(p.image,p.name)}<div><h3>${p.name}</h3><p class="muted">${money(p.price)} · Sample price</p></div><div><button data-qty="${p.id}" data-delta="-1" aria-label="Decrease ${p.name} quantity">−</button> <span>${cart[p.id]}</span> <button data-qty="${p.id}" data-delta="1" aria-label="Increase ${p.name} quantity">+</button></div><button data-remove="${p.id}" aria-label="Remove ${p.name}">Remove</button></div>`).join('')+`<p class="cart-total">Subtotal ${money(items.reduce((s,p)=>s+p.price*cart[p.id],0))}</p><p class="muted">Illustrative total. Delivery and taxes are not calculated. No payment will be taken.</p><a href="#checkout" class="button">Review your selection ↗</a>`:`<div class="empty"><h2>Your next favourite belongs here.</h2><p>Your bag is empty. Explore the collection to find a piece for your space.</p><a class="button" href="#shop">Explore the collection ↗</a></div>`}</section>`}
function custom(){return `<section class="page"><p class="eyebrow">MADE FOR YOUR KIND OF LIVING</p><h1>Something uniquely yours.</h1><p>A favourite shape, a particular fabric, a perfect fit. Start with an idea.</p><p class="note">Create a design brief to download and keep. This preview does not send quote requests.</p><form id="custom-form"><div class="form-grid"><label>Furniture type<select name="Furniture" required><option>Sofa</option><option>Chair</option><option>Dining table</option><option>Bed</option><option>Desk</option><option>Outdoor furniture</option></select></label><label>Dimensions (width × depth × height, cm)<input name="Dimensions" required maxlength="80" placeholder="e.g. 220 × 90 × 80 cm"></label><label>Material or fabric<input name="Material" required maxlength="100" placeholder="e.g. textured linen, natural wood"></label><label>Colour<input name="Colour" required maxlength="80" placeholder="e.g. terracotta"></label><label>Budget (TZS)<input name="Budget" type="number" min="1" required placeholder="Your approximate budget"></label><label>Delivery area<select name="Delivery area"><option>Kinondoni</option><option>Ilala</option><option>Temeke</option><option>Ubungo</option><option>Kigamboni</option><option>Elsewhere in Tanzania</option></select></label><label class="full">Tell us a little more<textarea name="Notes" maxlength="2000" placeholder="How will you use it? What details matter most?"></textarea></label><label class="full">Reference image (optional, JPG/PNG/WebP, maximum 5 MB)<input name="Reference" id="reference" type="file" accept="image/jpeg,image/png,image/webp"></label></div><button class="button">Review my design brief ↗</button></form><div id="brief-summary" aria-live="polite"></div></section>`}
const pages={story:['OUR ROOTS. YOUR HOME.','Warmth is where we begin.','AfroFurnitures is a contemporary furniture concept based in Dar es Salaam, Tanzania. Our direction is simple: furniture shaped by African warmth and modern life.','We look to natural textures, inviting proportions and thoughtful details. This showroom introduces our design direction; the photographs are inspiration images, and the collection is a sample catalogue.','Our next chapter is the real workshop story. Maker profiles, production details and verified sourcing will be added as the business takes shape.'],contact:['LET’S MAKE ROOM','A conversation worth having.','Dar es Salaam, Tanzania.','Showroom address, opening hours, business email and WhatsApp number have not yet been provided. Visits and WhatsApp enquiries will become available when these details are confirmed.','For now, explore the collection or prepare a custom furniture brief to keep for later.'],care:['LIVING WITH YOUR FURNITURE','A little care goes a long way.','Dust with a soft, dry cloth. Blot spills without rubbing, and avoid prolonged direct sunlight.','Use coasters on wood surfaces. Avoid harsh chemicals, abrasive cloths and excessive moisture. Always follow the final manufacturer’s instructions for your specific material.'],delivery:['THE PRACTICAL DETAILS','Delivery, thoughtfully planned.','Delivery fees, service areas, lead times, assembly services and returns policies have not been finalised.','The sample catalogue does not promise inventory or delivery dates. All order terms and the final total must be confirmed before purchase. No paid orders are accepted on this preview.'],privacy:['YOUR INFORMATION','Privacy & terms.','This is a demonstration showroom. Products, prices and specifications are sample data, and photographs illustrate the design direction.','Your bag and favourites are stored only in this browser. Your design brief is processed locally and is not submitted to a server. Clearing browser storage removes your saved selection.','The site loads a font from Google Fonts. Business privacy, sales and returns terms must be finalised before accepting customer orders.']};
function simple(key){const p=pages[key];return `<section class="page article"><p class="eyebrow">${p[0]}</p><h1>${p[1]}</h1>${key==='story'?photo('dining','Natural textures and warm wood'):''}${p.slice(2).map(t=>`<p>${t}</p>`).join('')}<div class="buttons"><a href="#shop" class="button">Explore the collection ↗</a><a href="#custom" class="text-link">Create a design brief ↗</a></div></section>`}
function article(id){return `<section class="page article"><p class="eyebrow">AFRO LIVING · THE EVERYDAY EDIT</p><h1>${id==='table'?'Make space for a longer conversation.':'A warmer way to come home.'}</h1>${photo(id==='table'?'dining':'hero','Interior inspiration')}<p>${id==='table'?'The dining table is more than a place to eat. It is where a quick cup of tea turns into an afternoon, where stories are shared and ordinary days become memories.':'Warmth begins with how a room feels. A terracotta seat, a natural texture, a pool of afternoon light: small choices can give a space a welcoming rhythm.'}</p><h2>Start with how you live.</h2><p>Leave room to move, choose a scale that suits your space, and keep the pieces you use most within easy reach. Measure the room and its doorways before choosing furniture.</p><h2>Let the materials speak.</h2><p>Pair wood with softer fabrics. Bring in a plant, a favourite book, or a piece with a story. A home grows more interesting when it reflects the people who live there.</p><a class="button" href="#shop">Find your next piece ↗</a></section>`}
function render(){const route=decodeURIComponent(location.hash.slice(1)||'home'),[page,arg]=route.split('/');document.title=(page==='home'?'Crafted for the Way You Live':page.replace(/^./,c=>c.toUpperCase()))+' | AfroFurnitures';if(page==='home'||page==='collections')main.innerHTML=home();else if(page==='shop'){main.innerHTML=shop(arg);filter()}else if(page==='product'){const p=products.find(p=>p.id===arg);main.innerHTML=p?`<section class="page"><p class="muted"><a href="#shop">Collection</a> / ${p.name}</p>${detail(p)}</section>`:simple('contact')}else if(page==='cart')main.innerHTML=bag();else if(page==='custom')main.innerHTML=custom();else if(page==='wishlist')main.innerHTML=`<section class="page"><p class="eyebrow">KEEP A LITTLE INSPIRATION</p><h1>Saved for your space.</h1><div class="products">${products.filter(p=>wishlist.includes(p.id)).map(card).join('')||'<div class="empty"><p>No saved pieces yet. Tap the heart on any product to keep it here.</p><a href="#shop" class="button">Explore the collection ↗</a></div>'}</div></section>`;else if(pages[page])main.innerHTML=simple(page);else if(page==='article')main.innerHTML=article(arg);else if(page==='inspiration')main.innerHTML=`<section class="page"><p class="eyebrow">NOTES ON LIVING WELL</p><h1>Afro Living.</h1><div class="journal"><a href="#article/warmth">${photo('hero','An orange sofa and plants')}<h3>A warmer way to come home. ↗</h3></a><a href="#article/table">${photo('dining','A warm dining room')}<h3>Make space for a longer conversation. ↗</h3></a></div></section>`;else if(page==='checkout')main.innerHTML=`<section class="page article"><p class="eyebrow">YOUR SELECTION</p><h1>A thoughtful next step.</h1>${Object.keys(cart).length?`<p>Your sample selection totals <strong>${money(products.reduce((s,p)=>s+p.price*(cart[p.id]||0),0))}</strong>, before unconfirmed delivery and taxes.</p><p>Online ordering and payments are not connected. No order has been placed. Save your selection as a text file to discuss once business contact details are available.</p><button class="button" data-action="download-cart">Download my selection ↓</button>`:'<p>Your bag is empty.</p>'}<p><a class="text-link" href="#cart">Back to your bag</a></p></section>`;else if(page==='credits')main.innerHTML=`<section class="page article"><h1>Behind the photographs.</h1><p>Stock images are used as design inspiration and do not depict actual AfroFurnitures inventory.</p><p><a class="text-link" href="https://unsplash.com/photos/G8rS7Sz9FiQ" target="_blank" rel="noopener">Living room — Jason Leung / Unsplash ↗</a></p><p><a class="text-link" href="https://unsplash.com/photos/t2mzF13kSpA" target="_blank" rel="noopener">Coral seat — Dário Gomes / Unsplash ↗</a></p><p><a class="text-link" href="https://www.pexels.com/photo/8113036/" target="_blank" rel="noopener">Dining room — Rachel Claire / Pexels ↗</a></p></section>`;else main.innerHTML=`<section class="page"><h1>Let’s find your way home.</h1><a class="button" href="#home">Back home ↗</a></section>`;document.querySelector('nav').classList.remove('open');save()}
function download(name,text){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'text/plain'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('input',e=>{if(e.target.id==='search')filter()});document.addEventListener('change',e=>{if(['category','sort','material'].includes(e.target.id))filter()});
document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(button.matches('.close'))document.querySelector('#modal').close();if(button.dataset.add)add(button.dataset.add);if(button.dataset.wish){const id=button.dataset.wish;wishlist=wishlist.includes(id)?wishlist.filter(x=>x!==id):[...wishlist,id];save();button.setAttribute('aria-pressed',wishlist.includes(id));button.textContent=wishlist.includes(id)?'♥':'♡';toast(wishlist.includes(id)?'Saved to your favourites':'Removed from favourites');if(location.hash==='#wishlist')render()}if(button.dataset.quick){const p=products.find(p=>p.id===button.dataset.quick);document.querySelector('#modal-body').innerHTML=detail(p);document.querySelector('#modal').showModal()}if(button.dataset.homeFilter){document.querySelectorAll('[data-home-filter]').forEach(b=>b.classList.toggle('active',b===button));document.querySelector('#home-products').innerHTML=products.filter(p=>button.dataset.homeFilter==='All'||p.category===button.dataset.homeFilter).map(card).join('')}if(button.dataset.qty){const id=button.dataset.qty;cart[id]=Math.min(99,cart[id]+Number(button.dataset.delta));if(cart[id]<=0)delete cart[id];save();render()}if(button.dataset.remove){delete cart[button.dataset.remove];save();render()}if(button.dataset.action==='menu')document.querySelector('nav').classList.toggle('open');if(button.dataset.action==='search'){location.hash='shop';setTimeout(()=>document.querySelector('#search')?.focus(),30)}if(button.dataset.action==='download-cart')download('AfroFurnitures-selection.txt','AfroFurnitures — sample selection, not an order\n\n'+products.filter(p=>cart[p.id]).map(p=>`${p.name} × ${cart[p.id]} — ${money(p.price*cart[p.id])}`).join('\n')+'\n\nSample prices. Availability, delivery and final total require confirmation.');});
document.addEventListener('submit',e=>{if(e.target.id!=='custom-form')return;e.preventDefault();const file=document.querySelector('#reference').files[0];if(file&&(file.size>5*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type))){toast('Please choose a JPG, PNG or WebP image under 5 MB.');return}const data=new FormData(e.target),lines=[...data].map(([key,value])=>`${key}: ${value instanceof File?(value.name||'None'):value}`),text='AfroFurnitures — design brief\nNot submitted. No quote or order has been created.\n\n'+lines.join('\n');const summary=document.querySelector('#brief-summary');summary.innerHTML=`<h2 style="margin-top:45px">Your idea, on paper.</h2><p>Review your brief below. Nothing has been submitted. The reference image remains on your device; the download includes its filename only.</p><div class="note">${lines.map(x=>`<p>${escapeHtml(x)}</p>`).join('')}</div><button class="button" id="download-brief" style="margin-top:20px">Download my brief ↓</button>`;document.querySelector('#download-brief').onclick=()=>download('AfroFurnitures-design-brief.txt',text);summary.scrollIntoView({behavior:'smooth'})});
document.addEventListener('click',e=>{if(e.target.closest('dialog a'))document.querySelector('#modal').close()});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'add_sample_furniture_to_bag',description:'Add a sample furniture design to the local shopping bag. Does not place an order.',inputSchema:{type:'object',properties:{productId:{type:'string',enum:products.map(p=>p.id)}},required:['productId'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input.productId!=='string')throw Error('A productId is required');add(input.productId);if(location.hash==='#cart')render();return{productId:input.productId,quantity:cart[input.productId],orderPlaced:false}}})).catch(()=>{})}catch{}}
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.tabIndex=-1;main.focus();main.scrollIntoView()});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
